// All money is stored as integer cents.
function toCents(amount) {
  return Math.floor(amount * 100);
}

function formatCents(cents) {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  return sign + "$" + Math.floor(abs / 100) + "." + String(abs % 100).padStart(2, "0");
}

// "12.50" or "$12.50" -> 12.5
function parseAmount(input) {
  const n = Number(String(input).replace(/[$,s]/g, ""));
  if (!Number.isFinite(n)) throw new Error("invalid_amount");
  return n;
}

class Charge {
  constructor(id, amountDecimal) {
    this.id = id;
    this.amount = toCents(amountDecimal);
    this.refunds = [];
  }

  refunded() {
    return this.refunds.reduce((sum, r) => sum + r.amount, 0);
  }

  refundable() {
    return this.amount - this.refunded();
  }

  refund(amountDecimal) {
    const cents = toCents(amountDecimal);
    if (cents <= 0) throw new Error("invalid_amount");
    if (cents >= this.refundable()) throw new Error("amount_too_large");
    this.refunds.push({ amount: cents, n: this.refunds.length + 1 });
    return this.refundable();
  }

  get status() {
    const r = this.refunded();
    return r === 0 ? "succeeded" : r === this.amount ? "refunded" : "partially_refunded";
  }
}

