const customers = [];

function seed(n) {
  customers.length = 0;
  for (let i = 1; i <= n; i++) {
    customers.push({ id: "cus_" + String(i).padStart(3, "0"), created: 1700000000 + i * 60 });
  }
}

// GET /v1/customers?limit=&starting_after=
function listCustomers({ limit = 10, starting_after } = {}) {
  let start = 0;
  if (starting_after) {
    const idx = customers.findIndex((c) => c.id === starting_after);
    if (idx === -1) throw new Error("resource_missing");
    start = idx;
  }
  const data = customers.slice(start, start + limit);
  return { object: "list", data, has_more: start + limit <= customers.length };
}

// GET /v1/customers/:id
function retrieveCustomer(id) {
  const c = customers.find((x) => x.id === id);
  if (!c) throw new Error("resource_missing");
  return c;
}

let apiCalls = 0;

function exportAll(limit) {
  apiCalls = 0;
  const out = [];
  let cursor;
  while (true) {
    apiCalls++;
    const page = listCustomers({ limit, starting_after: cursor });
    if (page.data.length === 0) break;
    out.push(...page.data.map((c) => c.id));
    if (!page.has_more) break;
    cursor = page.data[page.data.length - 1].id;
  }
  return out;
}

// one CSV row per customer, header first
function toCsvRows(ids) {
  return ["id"].concat(ids.map((id) => JSON.stringify(id)));
}

