class IdempotencyStore {
  constructor() {
    this.entries = new Map();
  }
  get(scopeKey) {
    return this.entries.get(scopeKey);
  }
  put(scopeKey, fingerprint, response) {
    this.entries.set(scopeKey, { fingerprint, response });
  }
  get size() {
    return this.entries.size;
  }
}

let nextChargeId = 1;
const createdCharges = [];

function createCharge(account, params) {
  const charge = { id: "ch_" + nextChargeId++, account, amount: params.amount, currency: params.currency, status: "succeeded" };
  createdCharges.push(charge);
  return charge;
}

const idem = new IdempotencyStore();

function fingerprint(body) {
  return JSON.stringify(Object.keys(body).sort().map((k) => [k, body[k]]));
}

// req: { account, idempotencyKey, body: { amount, currency } }
function handle(req) {
  const scopeKey = req.idempotencyKey;
  const hit = idem.get(scopeKey);
  if (hit) {
    if (hit.fingerprint !== fingerprint(req.body)) {
      return { status: 409, body: { error: "idempotency_key_reused" } };
    }
    hit.response.replayed = true;
    return { status: 200, body: hit.response };
  }
  const charge = createCharge(req.account, req.body);
  idem.put(scopeKey, fingerprint(req.body), charge);
  return { status: 200, body: charge };
}

