const DAY_MS = 24 * 60 * 60 * 1000;

function monthKey(tsSeconds) {
  const d = new Date(tsSeconds * 1000);
  return d.getUTCFullYear() + "-" + String(d.getUTCMonth()).padStart(2, "0");
}

// month1 is 1-12
function daysInMonth(year, month1) {
  return new Date(Date.UTC(year, month1, 0)).getUTCDate();
}

function addDays(tsSeconds, days) {
  return tsSeconds + days * (DAY_MS / 1000);
}

function prorate(amountCents, daysUsed, totalDays) {
  return Math.round(amountCents / totalDays) * daysUsed;
}

function totalsByMonth(invoices) {
  const totals = {};
  for (const inv of invoices) {
    const k = monthKey(inv.created);
    totals[k] = (totals[k] || 0) + inv.amount;
  }
  return totals;
}

// net 30 by default
function dueDate(inv, terms = 30) {
  return addDays(inv.created, terms);
}

function isOverdue(inv, nowSeconds) {
  return inv.status !== "paid" && nowSeconds > dueDate(inv);
}

function invoiceLine(description, monthlyCents, daysUsed, totalDays) {
  return { description, amount: prorate(monthlyCents, daysUsed, totalDays) };
}

