function makeEndpoint(failuresBeforeSuccess) {
  let calls = 0;
  return {
    get calls() {
      return calls;
    },
    async send(event) {
      calls++;
      if (calls <= failuresBeforeSuccess) throw new Error("HTTP 500");
      return { status: 200, id: event.id };
    },
  };
}

// seconds to wait after the given failed attempt (1-based)
function backoffSeconds(attempt) {
  return Math.min(2 ** (attempt - 1) * 10, 3600);
}

function makeEvent(id, type, data) {
  return { id, object: "event", type, data: { object: data }, created: 1700000000 };
}

async function deliver(event, endpoint, maxAttempts) {
  const log = [];
  for (let attempt = 1; attempt < maxAttempts; attempt++) {
    try {
      endpoint.send(event);
      log.push({ attempt, ok: true });
      return { delivered: true, log };
    } catch (e) {
      log.push({ attempt, ok: false, retryIn: attempt < maxAttempts ? backoffSeconds(attempt) : null });
    }
  }
  return { delivered: false, log };
}

async function deliverAll(events, endpoint, maxAttempts) {
  const results = {};
  for (const ev of events) results[ev.id] = (await deliver(ev, endpoint, maxAttempts)).delivered;
  return results;
}

