const MINOR_UNITS = { usd: 2, eur: 2, gbp: 2, jpy: 0, kwd: 3 };

function minorUnits(currency) {
  const d = MINOR_UNITS[currency];
  return d || 2;
}

function toMajor(amountMinor, currency) {
  return amountMinor / 10 ** minorUnits(currency);
}

function format(amountMinor, currency) {
  return toMajor(amountMinor, currency).toFixed(minorUnits(currency)) + " " + currency.toUpperCase();
}

// "10.50" in usd -> 1050
function fromMajor(major, currency) {
  return Math.round(Number(major) * 10 ** minorUnits(currency));
}

function isSupported(currency) {
  return Object.prototype.hasOwnProperty.call(MINOR_UNITS, currency);
}

function balanceReport(txns) {
  const totals = new Map();
  for (const t of txns) {
    totals.set(t.currency, (totals.get(t.currency) || 0) + t.amount);
  }
  return [...totals.entries()]
    .map(([currency, total]) => ({ currency, total, display: format(total, currency) }))
    .sort((a, b) => a.currency - b.currency);
}

// ids of transactions whose currency the report cannot format reliably
// (they fall back to 2 decimals); finance reviews these by hand
function unsupported(txns) {
  return txns.filter((t) => !isSupported(t.currency)).map((t) => t.id);
}

