// script: outcome per call ("ok" | "503_after_commit" | "400"); the last entry repeats
function makeGateway(script) {
  const charges = new Map();
  let call = 0;
  return {
    charges,
    get calls() {
      return call;
    },
    async post(body, idemKey) {
      const outcome = script[Math.min(call++, script.length - 1)];
      if (outcome === "400") return { status: 400, body: { error: "card_declined" } };
      if (!charges.has(idemKey)) charges.set(idemKey, { id: "ch_" + (charges.size + 1), amount: body.amount });
      if (outcome === "503_after_commit") return { status: 503, body: { error: "unavailable" } };
      return { status: 200, body: charges.get(idemKey) };
    },
  };
}

let keySeq = 0;
function newIdempotencyKey() {
  return "idem_" + ++keySeq;
}

function isRetryable(status) {
  return status >= 400;
}

async function chargeWithRetry(gateway, body, maxAttempts) {
  let last;
  let attempts = 0;
  while (attempts < maxAttempts) {
    attempts++;
    const key = newIdempotencyKey();
    last = await gateway.post(body, key);
    if (last.status === 200) return { ok: true, charge: last.body, attempts };
    if (!isRetryable(last.status)) break;
  }
  return { ok: false, error: last.body.error, attempts };
}

