const DEFAULT_SCHEDULE = { interval: "weekly", minimumCents: 1000, holdDays: [] };

function makeSchedule(overrides = {}) {
  const s = { ...DEFAULT_SCHEDULE };
  if (overrides.interval) s.interval = overrides.interval;
  if (overrides.minimumCents !== undefined) s.minimumCents = overrides.minimumCents;
  for (const d of overrides.holdDays || []) s.holdDays.push(d);
  return s;
}

function splitEvenly(totalCents, parts) {
  const base = totalCents / parts;
  const remainder = totalCents - base * parts;
  const out = [];
  for (let i = 0; i < parts; i++) out.push(base + (i < remainder ? 1 : 0));
  return out;
}

function planPayouts(balanceCents, schedule, parts) {
  if (balanceCents < schedule.minimumCents) return [];
  return splitEvenly(balanceCents, parts);
}

const WEEKDAYS = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];

function nextPayoutDate(isoDate, schedule) {
  const d = new Date(isoDate + "T00:00:00Z");
  const step = schedule.interval === "daily" ? 1 : 7;
  do {
    d.setUTCDate(d.getUTCDate() + step);
  } while (schedule.holdDays.includes(d.toISOString().slice(0, 10)));
  return d.toISOString().slice(0, 10);
}

// human-readable summary for the dashboard
// e.g. "weekly payouts, minimum 1000 cents, 0 hold day(s)"
function describe(schedule) {
  return schedule.interval + " payouts, minimum " + schedule.minimumCents + " cents, " + schedule.holdDays.length + " hold day(s)";
}

